package com.campusnova.knowledge;
import com.campusnova.model.*; import com.campusnova.repository.*; import com.campusnova.service.SemanticTextService; import org.springframework.stereotype.Component; import java.util.*;
/** Hybrid source with a hard relevance gate. Official records outrank FAQs and no weak hit is returned. */
@Component public class DatabaseKnowledgeSource implements KnowledgeSource { private final FaqRepository faqs; private final AnnouncementRepository announcements; private final OfficialKnowledgeRepository official; private final SemanticTextService semantic; public DatabaseKnowledgeSource(FaqRepository f,AnnouncementRepository a,OfficialKnowledgeRepository o,SemanticTextService s){faqs=f;announcements=a;official=o;semantic=s;} public List<KnowledgeDocument> findRelevant(String q,Collection<String> memory){List<KnowledgeDocument> all=new ArrayList<KnowledgeDocument>();for(OfficialKnowledge d:official.findByActiveTrueAndOfficialSourceTrueOrderByImportedAtDesc())all.add(new KnowledgeDocument(d.getTitle(),d.getCategory(),d.getTitle()+"\n"+d.getExtractedText(),d.isVerified(),true,d.getSourceUrl()));for(Faq f:faqs.findByActiveTrue())all.add(new KnowledgeDocument("FAQ: "+f.getQuestion(),f.getCategory().getName(),f.getQuestion()+"\n"+f.getAnswer()+"\n"+f.getKeywords(),false,false,null));for(Announcement a:announcements.findAll())all.add(new KnowledgeDocument("Announcement: "+a.getTitle(),"Announcements",a.getTitle()+"\n"+a.getBody(),false,false,null));List<Scored> scored=new ArrayList<Scored>();for(KnowledgeDocument d:all){double score=semantic.score(q,memory,d.getContent());int overlap=semantic.overlap(q,memory,d.getContent());if(relevant(q,d,score,overlap))scored.add(new Scored(d,score+(d.isOfficial()?.20:0)));}Collections.sort(scored,new Comparator<Scored>(){public int compare(Scored a,Scored b){return Double.compare(b.score,a.score);}});List<KnowledgeDocument> result=new ArrayList<KnowledgeDocument>();for(Scored s:scored)if(result.size()<4)result.add(s.document);return result;} private boolean relevant(String question,KnowledgeDocument d,double score,int overlap){if(semantic.hasStrongTopicMatch(question,d.getContent()))return true;return overlap>=2&&score>=.35;} private static class Scored{KnowledgeDocument document;double score;Scored(KnowledgeDocument d,double s){document=d;score=s;}} }
